  ionViewDidEnter() {
    this.route.queryParams.subscribe((data) => {
      if (data) {
        if (data.data) {
          this.routeData = JSON.parse(data.data);
          let schId = this.routeData.totalSclData.SchlId;
          this.schoolName = this.routeData.totalSclData.SchlNme;
          this.schoolId = parseInt(schId);
          this.classId = parseInt(this.routeData.clsSec.Class);
          this.secId = this.routeData.clsSec.Sec;
          this.cwsnService.cwsnP1Post("load", 0);
          this.healthCheckUpAnswerPage.checkLocalDB(2);
        }
        this.checkLocalDB();
      }
    });
  }

  checkLocalAddStd(stdIds, stdList) {
    debugger;
    let query =
      "SELECT * FROM cwsn_add_std_post" + " WHERE StuId in (" + stdIds + ")";
    this.sqliteDB.executeQuery(query).then((res) => {
      let temp: any = [];
      for (var i = 0; i < res.rows.length; i++) {
        temp.push(res.rows.item(i));
      }
      debugger;
      let cwsnStudent = [];
      let notCwsnStudent = [];

      stdList.map((cwsnStu) => {
        temp.forEach((obj) => {
          if (cwsnStu.StuId == obj.StuId && obj.DifferAbled == 99) {
            cwsnStu.cwsnStatus = 2;
          }
        });
        if (cwsnStu.cwsnStatus !== null) {
          cwsnStudent.push(cwsnStu);
        } else {
          notCwsnStudent.push(cwsnStu);
        }
      });
      this.cwsnStudentList = cwsnStudent;
      this.cwsnStudentList.sort((a, b) => {
        if (a.name < b.name) {
          return -1;
        }
        if (a.name > b.name) {
          return 1;
        }
        return 0;
      });
      this.notCwsnStudentList = notCwsnStudent;
      this.notCwsnStudentList.sort((a, b) => {
        if (a.name < b.name) {
          return -1;
        }
        if (a.name > b.name) {
          return 1;
        }
        return 0;
      });
    });
  }

  checkLocalDB() {
    debugger;
    let query =
      "SELECT * FROM cwsn_student_list" +
      ' WHERE school_key_id = "' +
      this.schoolId +
      '"' +
      ' And Class = "' +
      this.classId +
      '"' +
      ' And Sec = "' +
      this.secId +
      '"';
    this.sqliteDB.executeQuery(query).then((res) => {
      if (res.rows.length > 0) {
        // this.clustoers=[];
        let temp: any = [];
        for (var i = 0; i < res.rows.length; i++) {
          temp.push(res.rows.item(i));
        }
        // =========================
        let stdIds = "";
        temp.forEach((obj) => {
          if (stdIds) {
            stdIds = stdIds + "," + obj.StuId;
          } else {
            stdIds = obj.StuId;
          }
        });
        this.checkLocalAddStd(stdIds, temp);
        //  ===============================
      } else {
        this.alertService.warning("No students found");
      }
    });
  }

  onSync() {
    let query =
      "SELECT * FROM cwsn_student_list" +
      ' WHERE school_key_id = "' +
      this.schoolId +
      '"' +
      ' And Class = "' +
      this.classId +
      '"' +
      ' And Sec = "' +
      this.secId +
      '"' +
      ' And scrSts_Local = "' +
      2 +
      '"';
    this.sqliteDB.executeQuery(query).then(
      (res) => {
        if (res.rows.length > 0) {
          this.alertService.alert("Please Sync Data First");
        } else {
          let query =
            "DELETE FROM cwsn_student_list" +
            ' WHERE school_key_id = "' +
            this.schoolId +
            '"' +
            ' And Class = "' +
            this.classId +
            '"' +
            ' And Sec = "' +
            this.secId +
            '"';
          this.sqliteDB.executeQuery(query).then((res) => {
            if (res) {
              this.checkLocalDB();
            }
          });
        }
      },
      (error) => {},
    );
  }

